//! Reading the model: `inspect` and `elements`.

use crate::json::{Map, Value};
use crate::session::Session;

pub fn inspect(s: &Session) -> Value {
    let pr = &s.project;
    let mut m = Map::new();
    let mut counts = Map::new();
    for e in pr.elements.values() {
        let c = e.get("category").and_then(|c| c.as_str()).unwrap_or("").to_string();
        let n = counts.get(&c).and_then(|v| v.as_u64()).unwrap_or(0);
        counts.insert(&c, Value::u(n + 1));
    }
    m.insert("counts", Value::Obj(counts));
    m.insert("history", s.history().into());
    m.insert("language", pr.language().into());
    m.insert("name", pr.name().into());
    let levels: Vec<Value> = crate::commands::basic::level_ids_sorted(pr)
        .iter()
        .map(|id| {
            let e = pr.el(*id).unwrap();
            jobj! {"elevation" => e.get("elevation").cloned().unwrap_or(Value::Null), "id" => *id, "name" => e.get("name").cloned().unwrap_or(Value::Null)}
        })
        .collect();
    m.insert("levels", Value::Arr(levels));
    for (k, v) in crate::styles::inspect_entries(s) {
        m.insert(&k, v);
    }
    Value::Obj(m)
}

pub fn elements(s: &Session, p: &Value) -> Result<Value, String> {
    let pr = &s.project;
    let cat = p.get("category").and_then(|c| c.as_str()).map(|c| c.to_string());
    let mut out = Vec::new();
    for (id, e) in &pr.elements {
        let c = e.get("category").and_then(|c| c.as_str()).unwrap_or("");
        if let Some(want) = &cat {
            if c != want {
                continue;
            }
        }
        let mut x = e.clone();
        x.set("id", Value::u(*id));
        if c == "level" {
            x.set("computation_height", Value::f(1200.0));
        }
        if c == "pointcloud" {
            crate::cloud::element_view(pr, &mut x);
        }
        out.push(x);
    }
    let n = out.len();
    Ok(jobj! {"count" => n, "elements" => Value::Arr(out), "returned" => n})
}
//! Reading a command's parameters, with the errors the commands give.

use crate::json::Value;

pub type R<T> = Result<T, String>;

pub fn get<'a>(p: &'a Value, key: &str) -> Option<&'a Value> {
    match p.get(key) {
        Some(Value::Null) | None => None,
        Some(v) => Some(v),
    }
}

pub fn has(p: &Value, key: &str) -> bool {
    get(p, key).is_some()
}

/// Present in the object, even as null.
pub fn given(p: &Value, key: &str) -> bool {
    p.get(key).is_some()
}

pub fn num_of(v: &Value) -> Option<f64> {
    match v {
        Value::Num(n) => Some(n.as_f64()),
        _ => None,
    }
}

/// The largest length a command takes, in mm (1000 km).
pub const MAX_MM: f64 = 1e9;

/// A length in mm, within the model's reach.
pub fn mm_of(v: &Value) -> Option<f64> {
    let x = num_of(v)?;
    if x.is_finite() && x.abs() <= MAX_MM {
        Some(x)
    } else {
        None
    }
}

pub fn req_num(p: &Value, cmd: &str, key: &str) -> R<f64> {
    match get(p, key) {
        None => Err(format!("{}: `{}` in mm is required", cmd, key)),
        Some(v) => mm_of(v).ok_or_else(|| format!("{}: `{}` must be a number in mm, got {}", cmd, key, v.to_compact())),
    }
}

pub fn opt_num(p: &Value, cmd: &str, key: &str) -> R<Option<f64>> {
    match get(p, key) {
        None => Ok(None),
        Some(v) => mm_of(v)
            .map(Some)
            .ok_or_else(|| format!("{}: `{}` must be a number in mm, got {}", cmd, key, v.to_compact())),
    }
}

/// A number in some unit other than mm (degrees, percent…).
pub fn opt_num_unit(p: &Value, cmd: &str, key: &str, unit: &str) -> R<Option<f64>> {
    match get(p, key) {
        None => Ok(None),
        Some(v) => num_of(v)
            .map(Some)
            .ok_or_else(|| format!("{}: `{}` must be a number{}, got {}", cmd, key, unit, v.to_compact())),
    }
}

pub fn opt_text(p: &Value, cmd: &str, key: &str) -> R<Option<String>> {
    match get(p, key) {
        None => Ok(None),
        Some(Value::Str(s)) if s.chars().count() <= 256 => Ok(Some(s.clone())),
        Some(v) => Err(format!("{}: `{}` must be text of at most 256 characters, got {}", cmd, key, v.to_compact())),
    }
}

pub fn opt_bool(p: &Value, cmd: &str, key: &str) -> R<Option<bool>> {
    match get(p, key) {
        None => Ok(None),
        Some(Value::Bool(b)) => Ok(Some(*b)),
        Some(v) => Err(format!("{}: `{}` must be true or false, got {}", cmd, key, v.to_compact())),
    }
}

pub fn point_of(v: &Value) -> Option<[f64; 2]> {
    let a = v.as_arr()?;
    if a.len() != 2 {
        return None;
    }
    Some([mm_of(&a[0])?, mm_of(&a[1])?])
}

pub fn point3_of(v: &Value) -> Option<[f64; 3]> {
    let a = v.as_arr()?;
    if a.len() != 3 {
        return None;
    }
    Some([mm_of(&a[0])?, mm_of(&a[1])?, mm_of(&a[2])?])
}

pub fn req_point(p: &Value, cmd: &str, key: &str) -> R<[f64; 2]> {
    match get(p, key) {
        None => Err(format!("{}: `{}` [x, y] is required", cmd, key)),
        Some(v) => point_of(v).ok_or_else(|| format!("{}: `{}` must be a point [x, y] in mm, got {}", cmd, key, v.to_compact())),
    }
}

pub fn opt_point(p: &Value, cmd: &str, key: &str) -> R<Option<[f64; 2]>> {
    match get(p, key) {
        None => Ok(None),
        Some(v) => point_of(v)
            .map(Some)
            .ok_or_else(|| format!("{}: `{}` must be a point [x, y] in mm, got {}", cmd, key, v.to_compact())),
    }
}

/// A list of points; anything but a list of points reads as missing.
pub fn points_of(v: &Value) -> Option<Vec<[f64; 2]>> {
    let a = v.as_arr()?;
    a.iter().map(point_of).collect()
}

pub fn req_points(p: &Value, cmd: &str, key: &str) -> R<Vec<[f64; 2]>> {
    match get(p, key).and_then(points_of) {
        None => Err(format!("{}: `{}` [[x, y], …] is required", cmd, key)),
        Some(v) => Ok(v),
    }
}

pub fn opt_points(p: &Value, cmd: &str, key: &str) -> R<Option<Vec<[f64; 2]>>> {
    match get(p, key) {
        None => Ok(None),
        Some(v) => match points_of(v) {
            Some(pts) => Ok(Some(pts)),
            None => Err(format!("{}: `{}` [[x, y], …] is required", cmd, key)),
        },
    }
}

/// An element id: a number, or a GUID or an id in a string.
pub fn id_of(v: &Value) -> Option<u64> {
    match v {
        Value::Num(n) => {
            let f = n.as_f64();
            if f >= 0.0 && f.fract() == 0.0 {
                Some(f as u64)
            } else {
                None
            }
        }
        Value::Str(s) => s.trim().parse::<u64>().ok(),
        _ => None,
    }
}
//! Small shared tools: base64, FNV-1a.

const B64: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

pub fn base64_encode(data: &[u8]) -> String {
    let mut out = String::with_capacity((data.len() + 2) / 3 * 4);
    for c in data.chunks(3) {
        let b = [c[0], *c.get(1).unwrap_or(&0), *c.get(2).unwrap_or(&0)];
        let n = (b[0] as u32) << 16 | (b[1] as u32) << 8 | b[2] as u32;
        out.push(B64[(n >> 18) as usize & 63] as char);
        out.push(B64[(n >> 12) as usize & 63] as char);
        out.push(if c.len() > 1 { B64[(n >> 6) as usize & 63] as char } else { '=' });
        out.push(if c.len() > 2 { B64[n as usize & 63] as char } else { '=' });
    }
    out
}

pub fn base64_decode(s: &str) -> Option<Vec<u8>> {
    let mut out = Vec::with_capacity(s.len() / 4 * 3);
    let mut buf = 0u32;
    let mut n = 0;
    let mut pad = 0;
    for ch in s.bytes() {
        let v = match ch {
            b'A'..=b'Z' => ch - b'A',
            b'a'..=b'z' => ch - b'a' + 26,
            b'0'..=b'9' => ch - b'0' + 52,
            b'+' => 62,
            b'/' => 63,
            b'=' => {
                pad += 1;
                0
            }
            _ => return None,
        };
        if pad > 0 && ch != b'=' {
            return None;
        }
        buf = buf << 6 | v as u32;
        n += 1;
        if n == 4 {
            out.push((buf >> 16) as u8);
            out.push((buf >> 8) as u8);
            out.push(buf as u8);
            buf = 0;
            n = 0;
        }
    }
    if n != 0 || pad > 2 {
        return None;
    }
    out.truncate(out.len() - pad);
    Some(out)
}

pub fn fnv1a64(data: &[u8]) -> u64 {
    let mut h: u64 = 0xcbf29ce484222325;
    for &b in data {
        h ^= b as u64;
        h = h.wrapping_mul(0x100000001b3);
    }
    h
}
//! Random numbers for GUIDs and project uids, from the system's entropy.

use std::cell::RefCell;
use std::io::Read;

thread_local! {
    static STATE: RefCell<[u64; 4]> = RefCell::new(seed());
}

fn seed() -> [u64; 4] {
    let mut buf = [0u8; 32];
    let ok = std::fs::File::open("/dev/urandom").and_then(|mut f| f.read_exact(&mut buf)).is_ok();
    if !ok {
        use std::collections::hash_map::RandomState;
        use std::hash::{BuildHasher, Hasher};
        let t = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_nanos() as u64)
            .unwrap_or(0);
        for i in 0..4 {
            let mut h = RandomState::new().build_hasher();
            h.write_u64(t ^ (i as u64));
            buf[i * 8..i * 8 + 8].copy_from_slice(&h.finish().to_le_bytes());
        }
    }
    let mut s = [0u64; 4];
    for i in 0..4 {
        s[i] = u64::from_le_bytes(buf[i * 8..i * 8 + 8].try_into().unwrap());
    }
    if s == [0; 4] {
        s[0] = 0x9e3779b97f4a7c15;
    }
    s
}

/// xoshiro256** over the seed.
pub fn next_u64() -> u64 {
    STATE.with(|st| {
        let mut s = st.borrow_mut();
        let result = s[1].wrapping_mul(5).rotate_left(7).wrapping_mul(9);
        let t = s[1] << 17;
        s[2] ^= s[0];
        s[3] ^= s[1];
        s[1] ^= s[2];
        s[0] ^= s[3];
        s[2] ^= t;
        s[3] = s[3].rotate_left(45);
        result
    })
}

/// A random (version 4) GUID, lowercase and hyphenated.
pub fn guid() -> String {
    let a = next_u64();
    let b = next_u64();
    let mut bytes = [0u8; 16];
    bytes[..8].copy_from_slice(&a.to_be_bytes());
    bytes[8..].copy_from_slice(&b.to_be_bytes());
    bytes[6] = (bytes[6] & 0x0f) | 0x40;
    bytes[8] = (bytes[8] & 0x3f) | 0x80;
    let h: String = bytes.iter().map(|b| format!("{:02x}", b)).collect();
    format!("{}-{}-{}-{}-{}", &h[0..8], &h[8..12], &h[12..16], &h[16..20], &h[20..32])
}

/// Random alphanumeric characters, as tempfile names its files.
pub fn alnum(n: usize) -> String {
    const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    (0..n).map(|_| CHARS[(next_u64() % CHARS.len() as u64) as usize] as char).collect()
}
//! Scripts: one `id {json}` per line; blank lines and `#` comments are passed over.

use crate::json::Value;

pub struct Line {
    pub line: usize,
    pub id: String,
    pub params: Value,
}

/// Parses a whole script before anything runs, so a bad line stops it at once.
pub fn parse(text: &str) -> Result<Vec<Line>, String> {
    let mut out = Vec::new();
    for (n, raw) in text.lines().enumerate() {
        let t = raw.trim();
        if t.is_empty() || t.starts_with('#') {
            continue;
        }
        let (id, rest) = match t.find(char::is_whitespace) {
            Some(i) => (&t[..i], t[i..].trim()),
            None => (t, ""),
        };
        let params = if rest.is_empty() {
            Value::obj()
        } else {
            match crate::json::parse(rest) {
                Ok(v) => v,
                Err(e) => return Err(format!("line {}: bad JSON after `{}`: {}", n + 1, id, e)),
            }
        };
        out.push(Line { line: n + 1, id: id.to_string(), params });
    }
    Ok(out)
}

