"""Probe helpers: run the original (or mine) in a temp dir on a script; inspect results."""
import json, subprocess, tempfile, shutil, os, sys

ORIG = '/workspace/executable'
MINE = '/workspace/.claude/worktrees/agent-af4bed457bbf53b4c/target/release/bimcraft-cli'
FX = '/tmp/edit-agent/fx/all.bimcraft'


def run(cmds, args_before=(), args_after=(), files=(), exe=ORIG, keep=False, dirs=(), cwd_sub=None):
    """cmds: list of 'id {json}' lines written to s.txt (run --script s.txt).
    files: list of src or (src, dst) copied into the temp dir.
    Returns dict(code, out (list of lines), err, files {rel: bytes}, dir)."""
    d = tempfile.mkdtemp(prefix='r')
    for s in dirs:
        os.makedirs(os.path.join(d, s), exist_ok=True)
    for f in files:
        if isinstance(f, tuple):
            src, dst = f
        else:
            src, dst = f, os.path.basename(f)
        full = os.path.join(d, dst)
        os.makedirs(os.path.dirname(full), exist_ok=True)
        shutil.copy(src, full)
    args = [exe, 'run'] + list(args_before)
    if cmds is not None:
        open(os.path.join(d, 's.txt'), 'w').write('\n'.join(cmds) + '\n')
        args += ['--script', 's.txt']
    args += list(args_after)
    cwd = d if cwd_sub is None else os.path.join(d, cwd_sub)
    if cwd_sub is not None:
        os.makedirs(cwd, exist_ok=True)
        args = [a.replace('s.txt', os.path.join(d, 's.txt')) if a == 's.txt' else a for a in args]
    p = subprocess.run(args, cwd=cwd, capture_output=True, timeout=300)
    res = {'code': p.returncode, 'out': p.stdout.decode('utf-8', 'replace').splitlines(),
           'err': p.stderr.decode('utf-8', 'replace').strip(), 'files': {}, 'dir': d}
    for root, ds, fs in os.walk(d):
        for f in fs:
            full = os.path.join(root, f)
            res['files'][os.path.relpath(full, d)] = open(full, 'rb').read()
    if not keep:
        shutil.rmtree(d)
    return res


def j(line):
    try:
        return json.loads(line)
    except Exception:
        return line


def show(res, maxlen=600):
    print('code', res['code'])
    for l in res['out']:
        print('  >', l[:maxlen])
    if res['err']:
        print('  ERR', res['err'][:2000])


def proj(res, name):
    return json.loads(res['files'][name])


def make(script_lines, name, exe=ORIG, files=()):
    """Builds a project with the original from script lines; saves it to /tmp/edit-files/fx/name."""
    os.makedirs('/tmp/edit-files/fx', exist_ok=True)
    r = run(script_lines, args_after=['--save', 'out.bimcraft'], files=files, exe=exe)
    if r['code'] != 0:
        print('make failed', r['err'])
        sys.exit(1)
    open('/tmp/edit-files/fx/' + name, 'wb').write(r['files']['out.bimcraft'])
    return '/tmp/edit-files/fx/' + name

