exe = MINE if len(sys.argv) > 1 else ORIG
def go(cmds, files=[FX], save=True, pre=[], dump=True, **kw):
    r = run(cmds, files=files, args_before=pre, args_after=['--save', 'out.bimcraft'] if save else [], exe=exe, **kw)
    for l in r['out']:
        if l.startswith('{"counts"'):
            d = json.loads(l)
            print('  > inspect history', d['history'], 'counts', d['counts'], 'warnings', d.get('warnings'))
        else:
            print('  >', l[:3000])
    if r['err']:
        print('  ERR', r['err'][:700])
    if dump and 'out.bimcraft' in r['files']:
        p = proj(r, 'out.bimcraft')
        base = json.load(open(FX)) if pre else None
        for k, v in p['elements'].items():
            if base and k in base['elements'] and base['elements'][k] == v:
                continue
            print('   ', k, json.dumps(v)[:400])
        print('    next_id', p['next_id'])
    return r

for ids in ['[100007]', '[100031]', '[100009]', '[100030]', '[100032]', '[100008, 100003]', '[100026]', '[100033]', '[100035]', '[100028]', '[100029]', '[100027]', '[100000]', '[100001]']:
