import sys, json, os
sys.path.insert(0, '/tmp/edit-files')
from r import *

exe = MINE if len(sys.argv) > 1 else ORIG
LIB = '/tmp/edit-files/fx/lib.bimcraft'
EMPTY = '/tmp/edit-files/fx/empty.bimcraft'

def topdiff(a, b, pre=''):
    """print what differs between dicts a (before) and b (after), recursively for dicts"""
    for k in b:
        if k not in a:
            print(pre + '+', k, json.dumps(b[k], ensure_ascii=False)[:600])
        elif a[k] != b[k]:
            if isinstance(a[k], dict) and isinstance(b[k], dict) and k not in ('elements',):
                topdiff(a[k], b[k], pre + k + '.')
            elif k != 'elements':
                print(pre + '~', k, json.dumps(a[k], ensure_ascii=False)[:300], '=>', json.dumps(b[k], ensure_ascii=False)[:600])
    for k in a:
        if k not in b:
            print(pre + '-', k)

def go(cmds, base, files=[], pre=[], dump=True, ids=None):
    r = run(cmds, files=files + [base], args_before=[os.path.basename(base)], args_after=['--save', 'out.bimcraft'], exe=exe)
    for l in r['out'][1:]:
        print('  >', l[:3000])
    if r['err']:
        print('  ERR', r['err'][:700])
    if 'out.bimcraft' in r['files']:
        p = proj(r, 'out.bimcraft')
        b = json.load(open(base))
        topdiff({k: v for k, v in b.items() if k not in ('elements', 'uid')}, {k: v for k, v in p.items() if k not in ('elements', 'uid')})
        for k, v in p['elements'].items():
            if k in b['elements'] and b['elements'][k] == v:
                continue
            print('   ', k, json.dumps(v)[:600])
    return r

print('=== lib -> empty, all')
go(['insert {"path": "lib.bimcraft"}'], EMPTY, files=[LIB])

