    if isinstance(v, dict):
        if 'id' in v and isinstance(v['id'], int) and v['id'] >= 900000:
            out.append((v['id'], path, v.get('guid')))
        for k, x in v.items():
            walk(x, path + '.' + k)
    elif isinstance(v, list):
        for i, x in enumerate(v):
            walk(x, path + '[%d]' % i)
for k, v in d.items():
    if k == 'library':
        for kk, vv in v.items():
            if int(kk) >= lo:
                out.append((int(kk), 'library:' + vv['kind'] + ':' + vv['name'], vv['guid']))
    else:
        walk(v, k)
for i, p, g in sorted(out, reverse=True):
    if i >= lo:
        print(i, p, g)

