//! Autosave and Recover Autosave: recovery snapshots.
//!
//! `autosave {path}` writes the project as Save writes it (the same bytes), atomically (a hidden
//! temporary file beside it, renamed over it), and changes nothing else: the project keeps its
//! path, its undo history and its unsaved state. `recover {path, project?}` opens a snapshot as
//! Open does (the same reading, the same errors, after `open: `) and starts a new history; Save
//! then goes to `project`, or needs a path without it. The snapshot's links are read relative to
//! `project` (or as given without one).

use super::common::*;
use crate::commands::params::opt_text;
use crate::json::Value;
use crate::session::Session;

pub fn run(s: &mut Session, cid: &str, p: &Value) -> R<Value> {
    match cid {
        "autosave" => autosave(s, p),
        _ => recover(s, p),
    }
}

fn autosave(s: &mut Session, p: &Value) -> R<Value> {
    let path = match opt_text(p, "autosave", "path")? {
        Some(x) => x,
        None => return Err("autosave: `path` is required".into()),
    };
    let text = s.project.to_file_string();
    write_atomic(&path, text.as_bytes()).map_err(|e| format!("autosave: {}", e))?;
    Ok(crate::jobj! {"format" => "bimcraft", "path" => path})
}

fn recover(s: &mut Session, p: &Value) -> R<Value> {
    // the project to save to is read first, then the snapshot as Open reads a path
    let project = opt_text(p, "recover", "project")?;
    let path = match opt_text(p, "open", "path")? {
        Some(x) => x,
        None => return Err("open: `path` is required".into()),
    };
    let mut reply = crate::commands::basic::open_project_file(s, &path).map_err(|e| format!("open: {}", e))?;
    s.path = project;
    // its links stand relative to the project it is recovered for
    if let Value::Obj(m) = &mut reply {
        m.remove("links_not_loaded");
    }
    let failed = super::link::load_all(s);
    if !failed.is_empty() {
        reply.set("links_not_loaded", Value::Arr(failed));
    }
    Ok(reply)
}

/// Writes a file as tempfile's NamedTempFile and persist do, with their errors after the path:
/// `x: <error> at path "<the temporary file>"` when the temporary file can't be made or written,
/// `x: failed to persist temporary file: <error>` when it can't be renamed over the file.
pub fn write_atomic(path: &str, bytes: &[u8]) -> Result<(), String> {
    use std::io::Write;
    use std::os::unix::fs::OpenOptionsExt;
    let p = std::path::Path::new(path);
    let parent = match p.parent() {
        Some(d) if !d.as_os_str().is_empty() => d.to_path_buf(),
        _ => std::path::PathBuf::from(""),
    };
    let dir = if parent.is_absolute() {
        parent
    } else {
        std::env::current_dir().map_err(|e| format!("{}: {}", path, e))?.join(parent)
    };
    let tmp = dir.join(format!(".tmp{}", crate::rand::alnum(6)));
    let at = |e: std::io::Error| format!("{}: {} at path {:?}", path, e, tmp.to_string_lossy());
    let mut f = std::fs::OpenOptions::new().write(true).create_new(true).mode(0o600).open(&tmp).map_err(at)?;
    if let Err(e) = f.write_all(bytes) {
        drop(f);
        let _ = std::fs::remove_file(&tmp);
        return Err(at(e));
    }
    drop(f);
    if let Err(e) = std::fs::rename(&tmp, p) {
        let _ = std::fs::remove_file(&tmp);
        return Err(format!("{}: failed to persist temporary file: {}", path, e));
    }
    Ok(())
}

#[allow(dead_code)]
fn _uses(_: R<()>) {}

//! Link Model and Reload Links: other projects shown in this one as references.
//!
//! A link is an element, `{guid, category: "link", name, path, at, angle?}` (`angle` only when it
//! isn't 0), its `path` kept as given: a relative one is read relative to the project's file (to
//! where the program runs while the project has none). What was read of its file is held by the
//! session, not the project: `elements` shows how many elements it has (`null` and `loaded:
//! false` until it is read), `reload` reads it again, and opening a project reads them all,
//! saying which it couldn't (`links_not_loaded`).

use super::common::*;
use crate::commands::params::{opt_num, opt_point, opt_text};
use crate::json::Value;
use crate::project::Project;
use crate::session::Session;
use std::cell::RefCell;
use std::collections::HashMap;

/// What was read of a link's file: its elements' count, or why it couldn't be read.
#[derive(Clone, Debug)]
pub struct Loaded {
    pub elements: Option<usize>,
    pub error: Option<String>,
}

thread_local! {
    /// Each link's file as last read, by the link's GUID.
    static LOADED: RefCell<HashMap<String, Loaded>> = RefCell::new(HashMap::new());
}

fn set_loaded(guid: &str, l: Loaded) {
    LOADED.with(|m| {
        m.borrow_mut().insert(guid.to_string(), l);
    });
}

fn get_loaded(guid: &str) -> Option<Loaded> {
    LOADED.with(|m| m.borrow().get(guid).cloned())
}

/// Forgets what was read for this link (a link that comes in by `insert` isn't read yet).
pub fn forget(guid: &str) {
    LOADED.with(|m| {
        m.borrow_mut().remove(guid);
    });
}

pub fn run(s: &mut Session, cid: &str, p: &Value) -> R<Value> {
    match cid {
        "link" => link(s, p),
        _ => reload(s, p),
    }
}

// ---------------------------------------------------------------- reading a project file

/// Reads a project file (or an IFC file) as Open reads it, into a project of its own; the error
/// is what Open says after `open: ` (`x: No such file or directory (os error 2)`, `x is not a
/// BIMCraft project: …`), the path as given.
pub fn read_project(path: &str) -> Result<Project, String> {
    let low = path.to_lowercase();
    if low.ends_with(".ifc") {
        let mut tmp = Session::new();
        crate::ifc::import::import(&mut tmp, path)?;
        return Ok(tmp.project);
    }
    let text = std::fs::read_to_string(path).map_err(|e| format!("{}: {}", path, e))?;
    let v = crate::json::parse(&text).map_err(|e| format!("{} is not a BIMCraft project: {}", path, e))?;
    let proj = crate::load::load(v).map_err(|e| format!("{} is not a BIMCraft project: {}", path, e))?;
    crate::cloud::check(&proj).map_err(|e| format!("{}: {}", path, e))?;
    Ok(proj)
}

/// Where a link's file is: its path as given when absolute or when the project has no file,
/// else beside the project's file (`sub/p.bimcraft` and `x.bimcraft` read `sub/x.bimcraft`).
pub fn resolve_path(project_path: Option<&str>, path: &str) -> String {
    let p = std::path::Path::new(path);
    if p.is_absolute() {
        return path.to_string();
    }
    match project_path {
        Some(pp) => match std::path::Path::new(pp).parent() {
            Some(dir) => dir.join(p).to_string_lossy().to_string(),
            None => path.to_string(),
        },
        None => path.to_string(),
    }
}

fn read_link(project_path: Option<&str>, path: &str) -> Loaded {
    let full = resolve_path(project_path, path);
    match read_project(&full) {
        Ok(pr) => Loaded { elements: Some(pr.elements.len()), error: None },
        Err(e) => Loaded { elements: None, error: Some(e) },
    }
}

/// The links of the project, in id order: (id, guid, name, path).
fn links(pr: &Project) -> Vec<(u64, String, String, String)> {
    pr.elements
        .iter()
        .filter(|(_, e)| cat_of(e) == "link")
        .map(|(id, e)| {
            let g = e.get("guid").and_then(|x| x.as_str()).unwrap_or("").to_string();
            let n = e.get("name").and_then(|x| x.as_str()).unwrap_or("").to_string();
            let p = e.get("path").and_then(|x| x.as_str()).unwrap_or("").to_string();
            (*id, g, n, p)
        })
        .collect()
}

/// Reads every link's file (as opening a project does); the ones it couldn't, `{error, name}`,
/// in id order.
pub fn load_all(s: &Session) -> Vec<Value> {
    let mut failed = Vec::new();
    for (_, g, name, path) in links(&s.project) {
        let l = read_link(s.path.as_deref(), &path);
        if let Some(e) = &l.error {
            failed.push(crate::jobj! {"error" => e.clone(), "name" => name.clone()});
        }
        set_loaded(&g, l);
    }
    failed
}

/// What `elements` shows of a link beyond its fields: `elements`, the count of its file's
/// elements as last read (null when it couldn't be, or hasn't been, read), and `loaded`.
pub fn element_view(e: &mut Value) {
    let g = e.get("guid").and_then(|x| x.as_str()).unwrap_or("").to_string();
    let l = get_loaded(&g).unwrap_or(Loaded { elements: None, error: None });
    e.set("elements", l.elements.map(|n| Value::u(n as u64)).unwrap_or(Value::Null));
    e.set("loaded", Value::Bool(l.elements.is_some()));
}

// ---------------------------------------------------------------- link

fn file_stem(path: &str) -> String {
    std::path::Path::new(path)
        .file_stem()
        .map(|s| s.to_string_lossy().to_string())
        .unwrap_or_default()
}

fn link(s: &mut Session, p: &Value) -> R<Value> {
    let path = match opt_text(p, "link", "path")? {
        Some(x) => x,
        None => return Err("link: `path` is required".into()),
    };
    // the file is read before the rest is looked at
    let full = resolve_path(s.path.as_deref(), &path);
    let linked = read_project(&full).map_err(|e| format!("link: {}", e))?;
    let name = opt_text(p, "link", "name")?;
    let at = opt_point(p, "link", "at")?.unwrap_or([0.0, 0.0]);
    let angle = opt_num(p, "link", "angle")?.unwrap_or(0.0);
    let name = name.unwrap_or_else(|| file_stem(&path));
    let pr = &mut s.project;
    let id = pr.alloc_id();
    let guid = crate::rand::guid();
    let mut e = crate::jobj! {
        "guid" => guid.clone(),
        "category" => "link",
        "name" => name.clone(),
        "path" => path,
        "at" => Value::Arr(vec![Value::f(at[0]), Value::f(at[1])]),
    };
    if angle != 0.0 {
        e.set("angle", Value::f(angle));
    }
    pr.elements.insert(id, e);
    let n = linked.elements.len();
    set_loaded(&guid, Loaded { elements: Some(n), error: None });
    Ok(crate::jobj! {"elements" => n, "id" => id, "name" => name})
}

// ---------------------------------------------------------------- reload

fn reload(s: &mut Session, p: &Value) -> R<Value> {
    let only: Option<u64> = match p.get("id") {
        None | Some(Value::Null) => None,
        Some(v) => {
            let bad = || format!("reload: `id` must be an element id or GUID, got {}", v.to_compact());
            let id = match v {
                Value::Num(n) => num_id(n).ok_or_else(bad)?,
                Value::Str(t) => {
                    let t = t.trim();
                    if let Ok(id) = t.parse::<u64>() {
                        id
                    } else if let Some(g) = strict_guid(t) {
                        match s.project.find_guid(&g) {
                            Some(id) => id,
                            None => return Err(format!("reload: element {} is not a link", t)),
                        }
                    } else {
                        return Err(bad());
                    }
                }
                _ => return Err(bad()),
            };
            if s.project.category(id) != Some("link") {
                return Err(format!("reload: element {} is not a link", id));
            }
            Some(id)
        }
    };
    let mut reloaded = Vec::new();
    let mut failed = Vec::new();
    for (id, g, name, path) in links(&s.project) {
        if only.map(|o| o != id).unwrap_or(false) {
            continue;
        }
        let l = read_link(s.path.as_deref(), &path);
        match &l.error {
            Some(e) => failed.push(crate::jobj! {"error" => e.clone(), "name" => name.clone()}),
            None => reloaded.push(Value::s(&name)),
        }
        set_loaded(&g, l);
    }
    Ok(crate::jobj! {"failed" => Value::Arr(failed), "reloaded" => Value::Arr(reloaded)})
}

// ---------------------------------------------------------------- the model's rules

/// Each link has a name and a path of a file, up to 256 characters, an angle within a turn either
/// way, and a name of its own among the links.
pub fn check(pr: &Project) -> R<()> {
    let mut names: Vec<String> = Vec::new();
    for (id, e) in &pr.elements {
        if cat_of(e) != "link" {
            continue;
        }
        let name = e.get("name").and_then(|x| x.as_str()).unwrap_or("");
        let path = e.get("path").and_then(|x| x.as_str()).unwrap_or("");
        if name.trim().is_empty() || name.chars().count() > 256 || path.is_empty() || path.chars().count() > 256 {
            return Err(format!("link {}: a link needs a name and the path of a file, up to 256 characters", id));
        }
        if let Some(a) = e.get("angle").and_then(|x| x.as_f64()) {
            if !(-360.0..=360.0).contains(&a) {
                return Err(format!("link {}: its angle {}° isn't between -360° and 360°", id, a));
            }
        }
        if names.iter().any(|n| n == name) {
            return Err(format!("link {}: another link is already named `{}`", id, name));
        }
        names.push(name.to_string());
    }
    Ok(())
}

//! Insert from File, its library: what the other project's library has that this one hasn't (by
//! GUID, then by kind and name) comes in, each entry with its GUID and a new id of this library's,
//! taken in the other library's id order; a family's types and parameters after every other
//! entry. Phases, phase filters, view templates, view filters and design options don't: what names
//! one of them is matched to this project's by name, or is left out.

use crate::json::{Map, Value};
use crate::project::Project;
use std::collections::{HashMap, HashSet};

/// The parts of the file a library entry of this kind lives in: the section, and within `types`
/// the category (and `runs` for the run types).
pub fn place_of(kind: &str) -> Option<(&'static str, Option<&'static str>, Option<String>)> {
    if let Some(cat) = kind.strip_prefix("type:") {
        const RUNS: &[&str] = &[
            "beam",
            "stripfooting",
            "pipe",
            "duct",
            "conduit",
            "cabletray",
            "wire",
            "downconductor",
            "groundconductor",
            "cable",
        ];
        if RUNS.contains(&cat) {
            return Some(("types", Some("runs"), Some(cat.to_string())));
        }
        let key = match cat {
            "structuralcolumn" => "structural_column".to_string(),
            c => c.to_string(),
        };
        return Some(("types", None, Some(key)));
    }
    let sec = match kind {
        "material" => "materials",
        "picture" => "images",
        "cloud" => "clouds",
        "cad" => "cads",
        "family" => "families",
        "parameter" => "parameters",
        "line-pattern" => "line_patterns",
        "line-style" => "line_styles",
        "fill-pattern" => "fill_patterns",
        "filled-region-type" => "region_types",
        "text-type" => "text_types",
        "dimension-type" => "dimension_types",
        "detail-group" => "detail_groups",
        "voltage" => "voltages",
        "distribution-system" => "distribution_systems",
        "wire-type" => "wire_types",
        _ => return None,
    };
    Some((sec, None, None))
}

/// How the reply names an entry that came in: `wall type: Exterior`, `fill pattern: Sand`.
pub fn label(kind: &str, name: &str) -> String {
    let words = if let Some(cat) = kind.strip_prefix("type:") {
        format!("{} type", cat)
    } else {
        match kind {
            "cloud" => "scan".to_string(),
            "cad" => "CAD drawing".to_string(),
            k => k.replace('-', " "),
        }
    };
    format!("{}: {}", words, name)
}

fn is_sub(kind: &str) -> bool {
    kind == "family-type" || kind == "family-parameter"
}

fn kind_of(e: &Value) -> &str {
    e.get("kind").and_then(|x| x.as_str()).unwrap_or("")
}
fn name_of(e: &Value) -> &str {
    e.get("name").and_then(|x| x.as_str()).unwrap_or("")
}
fn guid_of(e: &Value) -> &str {
    e.get("guid").and_then(|x| x.as_str()).unwrap_or("")
}

/// An entry of the other library that has no match here and can't come in: its kind and name
/// (and for a family's type or parameter, the family here and its own name in it).
#[derive(Clone, Debug)]
pub struct Unresolved {
    pub kind: String,
    pub name: String,
    pub family: Option<String>,
    pub sub: Option<String>,
}

#[derive(Default)]
pub struct LibMerge {
    /// The other library's GUIDs to this one's.
    pub gmap: HashMap<String, String>,
    pub unresolved: HashMap<String, Unresolved>,
    pub labels: Vec<String>,
    /// The entries that came in, as (kind, name), in the order they came.
    pub imported: Vec<(String, String)>,
}

// ---------------------------------------------------------------- ids

/// Every id the library and the parts of the project hold (library entries, a type's layers, a
/// family's forms, a region's sketch lines…).
pub fn used_ids(pr: &Project) -> HashSet<u64> {
    let mut out: HashSet<u64> = pr.library.keys().cloned().collect();
    for (k, v) in &pr.doc.items {
        if k != "elements" && k != "library" {
            part_ids(v, &mut out);
        }
    }
    for e in pr.elements.values() {
        part_ids(e, &mut out);
    }
    out
}

/// Whether an object is a part: an id of the library's (a number from 900000) and a GUID.
pub fn part_id(m: &Map) -> Option<u64> {
    let id = match m.get("id") {
        Some(Value::Num(n)) => {
            let x = n.as_f64();
            if x >= 900000.0 && x < 1_000_000.0 && x.fract() == 0.0 {
                x as u64
            } else {
                return None;
            }
        }
        _ => return None,
    };
    if matches!(m.get("guid"), Some(Value::Str(_))) {
        Some(id)
    } else {
        None
    }
}

fn part_ids(v: &Value, out: &mut HashSet<u64>) {
    match v {
        Value::Obj(m) => {
            if let Some(id) = part_id(m) {
                out.insert(id);
            }
            for (_, x) in &m.items {
                part_ids(x, out);
            }
        }
        Value::Arr(a) => a.iter().for_each(|x| part_ids(x, out)),
        _ => {}
    }
}

/// The lowest id the library and the parts use, the project's elements' parts with them.
pub fn lowest(pr: &Project) -> u64 {
    let mut low = 1_000_000u64.min(pr.lib_low);
    for id in used_ids(pr) {
        low = low.min(id);
    }
    low
}

/// A new id of the library's: one under every id handed out.
pub fn alloc(pr: &mut Project) -> u64 {
    let id = lowest(pr) - 1;
    pr.lib_low = id;
    id
}

// ---------------------------------------------------------------- GUIDs in what is copied

/// Replaces the GUIDs a value holds (as strings, or as keys: an element's parameter values are
/// keyed by the parameter) by what `map` says; a part's own `guid` is left as it is.
pub fn remap(v: &mut Value, map: &dyn Fn(&str) -> Option<String>) {
    match v {
        Value::Str(s) => {
            if let Some(n) = map(s) {
                *s = n;
            }
        }
        Value::Arr(a) => a.iter_mut().for_each(|x| remap(x, map)),
        Value::Obj(m) => {
            for (k, x) in m.items.iter_mut() {
                if k == "guid" {
                    continue;
                }
                if let Some(n) = map(k) {
                    *k = n;
                }
                remap(x, map);
            }
        }
        _ => {}
    }
}

// ---------------------------------------------------------------- the merge

fn section_entry<'a>(pr: &'a Project, kind: &str, name: &str) -> Option<&'a Value> {
    let (sec, runs, cat) = place_of(kind)?;
    let mut m = pr.section(sec)?;
    if let Some(r) = runs {
        m = m.get(r)?.as_obj()?;
    }
    if let Some(c) = &cat {
        m = m.get(c)?.as_obj()?;
    }
    m.get(name)
}

/// The order of `types`' categories in a file.
const TYPE_ORDER: &[&str] = &[
    "wall",
    "floor",
    "door",
    "window",
    "column",
    "roof",
    "ceiling",
    "railing",
    "structural_column",
    "footing",
    "runs",
];

fn insert_entry(pr: &mut Project, kind: &str, name: &str, v: Value) {
    let Some((sec, runs, cat)) = place_of(kind) else { return };
    let mut m = pr.section_mut(sec);
    if let Some(r) = runs {
        m = sub_map(m, r, TYPE_ORDER);
    }
    if let Some(c) = &cat {
        m = if runs.is_some() { sub_map_sorted(m, c) } else { sub_map(m, c, TYPE_ORDER) };
    }
    m.insert_sorted(name, v);
}

/// The map under `key`, made where `order` puts it if it isn't there.
fn sub_map<'a>(m: &'a mut Map, key: &str, order: &[&str]) -> &'a mut Map {
    if !m.contains(key) {
        let rank = |k: &str| order.iter().position(|o| *o == k).unwrap_or(usize::MAX);
        let r = rank(key);
        let pos = m.items.iter().position(|(k, _)| rank(k) > r).unwrap_or(m.items.len());
        m.items.insert(pos, (key.to_string(), Value::obj()));
    }
    let v = m.get_mut(key).unwrap();
    if !matches!(v, Value::Obj(_)) {
        *v = Value::obj();
    }
    v.as_obj_mut().unwrap()
}

fn sub_map_sorted<'a>(m: &'a mut Map, key: &str) -> &'a mut Map {
    if !m.contains(key) {
        m.insert_sorted(key, Value::obj());
    }
    let v = m.get_mut(key).unwrap();
    if !matches!(v, Value::Obj(_)) {
        *v = Value::obj();
    }
    v.as_obj_mut().unwrap()
}

/// The family a family's type or parameter entry (`Family: Name`) is of, among `families`: the
/// longest family name it starts with, then `: `.
fn split_sub(name: &str, families: &[String]) -> Option<(String, String)> {
    let mut best: Option<&String> = None;
    for f in families {
        if name.len() > f.len() + 2 && name.starts_with(f.as_str()) && name[f.len()..].starts_with(": ") {
            if best.map(|b| f.len() > b.len()).unwrap_or(true) {
                best = Some(f);
            }
        }
    }
    let f = best?;
    Some((f.clone(), name[f.len() + 2..].to_string()))
}

/// Brings in what the other project's library has that this one hasn't.
pub fn merge(pr: &mut Project, src: &Project) -> LibMerge {
    let mut m = LibMerge::default();
    let target_ids = used_ids(pr);
    let src_families: Vec<String> = src
        .library
        .values()
        .filter(|e| kind_of(e) == "family")
        .map(|e| name_of(e).to_string())
        .collect();
    // the family each family entry of the other library is here (by its name here)
    let mut family_here: HashMap<String, String> = HashMap::new();
    let mut family_in: HashSet<String> = HashSet::new();
    for e in src.library.values() {
        let (kind, name, g) = (kind_of(e).to_string(), name_of(e).to_string(), guid_of(e).to_string());
        if is_sub(&kind) {
            continue;
        }
        if pr.lib_find_guid(&g).is_some() {
            if kind == "family" {
                let here = pr.lib_name(&g).unwrap_or_else(|| name.clone());
                family_here.insert(name.clone(), here);
            }
            m.gmap.insert(g.clone(), g);
            continue;
        }
        if let Some(tg) = pr.lib_guid(&kind, &name) {
            if kind == "family" {
                family_here.insert(name.clone(), name.clone());
            }
            m.gmap.insert(g, tg);
            continue;
        }
        if place_of(&kind).is_none() {
            m.unresolved.insert(g, Unresolved { kind, name, family: None, sub: None });
            continue;
        }
        let id = alloc(pr);
        pr.library.insert(id, crate::jobj! {"kind" => kind.clone(), "name" => name.clone(), "guid" => g.clone()});
        m.gmap.insert(g.clone(), g);
        m.labels.push(label(&kind, &name));
        if kind == "family" {
            family_in.insert(name.clone());
        }
        m.imported.push((kind, name));
    }
    // a family's types and parameters: with a family that came in, they come; else they are the
    // family's here of the same name
    for e in src.library.values() {
        let (kind, name, g) = (kind_of(e).to_string(), name_of(e).to_string(), guid_of(e).to_string());
        if !is_sub(&kind) {
            continue;
        }
        if pr.lib_find_guid(&g).is_some() {
            m.gmap.insert(g.clone(), g);
            continue;
        }
        let Some((fam, sub)) = split_sub(&name, &src_families) else {
            m.unresolved.insert(g, Unresolved { kind, name, family: None, sub: None });
            continue;
        };
        if family_in.contains(&fam) {
            let id = alloc(pr);
            pr.library.insert(id, crate::jobj! {"kind" => kind.clone(), "name" => name.clone(), "guid" => g.clone()});
            m.gmap.insert(g.clone(), g);
            continue;
        }
        let here = family_here.get(&fam).cloned().unwrap_or(fam.clone());
        let here_name = format!("{}: {}", here, sub);
        match pr.lib_guid(&kind, &here_name) {
            Some(tg) => {
                m.gmap.insert(g, tg);
            }
            None => {
                m.unresolved.insert(g, Unresolved { kind, name, family: Some(here), sub: Some(sub) });
            }
        }
    }
    // what came in, as the other file has it, its GUIDs made this project's
    let gmap = m.gmap.clone();
    let map = move |s: &str| gmap.get(s).filter(|t| t.as_str() != s).cloned();
    for (kind, name) in &m.imported {
        if let Some(v) = section_entry(src, kind, name) {
            let mut v = v.clone();
            remap(&mut v, &map);
            insert_entry(pr, kind, name, v);
        }
    }
    // their parts keep their ids unless this project has them, in the order of the file
    renumber_parts(pr, &m.imported, target_ids);
    m
}

/// Gives the parts of what came in ids of their own where theirs are taken: in the order the
/// file holds them, each a new id under the lowest the project holds.
fn renumber_parts(pr: &mut Project, imported: &[(String, String)], target_ids: HashSet<u64>) {
    let mut used: HashSet<u64> = target_ids;
    used.extend(pr.library.keys().cloned());
    // the entries that came in, by where they are
    let mut came: HashSet<(String, Option<String>, String)> = HashSet::new();
    for (kind, name) in imported {
        if let Some((sec, runs, cat)) = place_of(kind) {
            let path = match (runs, cat) {
                (Some(r), Some(c)) => Some(format!("{}/{}", r, c)),
                (None, Some(c)) => Some(c),
                _ => None,
            };
            came.insert((sec.to_string(), path, name.clone()));
        }
    }
    let keys: Vec<String> = pr.doc.items.iter().map(|(k, _)| k.clone()).collect();
    for sec in keys {
        if sec == "elements" || sec == "library" {
            continue;
        }
        // the entries of this section, by their path in it
        let mut entries: Vec<(Option<String>, String)> = Vec::new();
        if let Some(Value::Obj(m)) = pr.doc.get(&sec) {
            if sec == "types" {
                for (c, ts) in m.iter() {
                    if c == "runs" {
                        if let Some(rm) = ts.as_obj() {
                            for (rc, rts) in rm.iter() {
                                if let Some(rts) = rts.as_obj() {
                                    for (n, _) in rts.iter() {
                                        entries.push((Some(format!("runs/{}", rc)), n.clone()));
                                    }
                                }
                            }
                        }
                    } else if let Some(ts) = ts.as_obj() {
                        for (n, _) in ts.iter() {
                            entries.push((Some(c.clone()), n.clone()));
                        }
                    }
                }
            } else {
                for (n, _) in m.iter() {
                    entries.push((None, n.clone()));
                }
            }
        }
        for (path, name) in entries {
            if !came.contains(&(sec.clone(), path.clone(), name.clone())) {
                continue;
            }
            let mut v = take_entry(pr, &sec, path.as_deref(), &name);
            renumber_in(pr, &mut v, &mut used, false);
            put_entry(pr, &sec, path.as_deref(), &name, v);
        }
    }
}

fn entry_mut<'a>(pr: &'a mut Project, sec: &str, path: Option<&str>, name: &str) -> Option<&'a mut Value> {
    let mut m = pr.doc.get_mut(sec)?.as_obj_mut()?;
    if let Some(p) = path {
        for part in p.split('/') {
            m = m.get_mut(part)?.as_obj_mut()?;
        }
    }
    m.get_mut(name)
}

fn take_entry(pr: &mut Project, sec: &str, path: Option<&str>, name: &str) -> Value {
    entry_mut(pr, sec, path, name).map(std::mem::take).unwrap_or(Value::Null)
}

fn put_entry(pr: &mut Project, sec: &str, path: Option<&str>, name: &str, v: Value) {
    if let Some(slot) = entry_mut(pr, sec, path, name) {
        *slot = v;
    }
}

/// Gives the parts in `v` ids of their own where theirs are in `used` (new GUIDs too when
/// `copy`), in the order `v` holds them.
pub fn renumber_in(pr: &mut Project, v: &mut Value, used: &mut HashSet<u64>, copy: bool) {
    // the parts' ids, as they are, count while new ones are found
    let mut held: Vec<u64> = Vec::new();
    collect_part_ids(v, &mut held);
    let floor = held.iter().cloned().min();
    renumber_walk(pr, v, used, copy, floor);
}

fn collect_part_ids(v: &Value, out: &mut Vec<u64>) {
    match v {
        Value::Obj(m) => {
            if let Some(id) = part_id(m) {
                out.push(id);
            }
            for (_, x) in &m.items {
                collect_part_ids(x, out);
            }
        }
        Value::Arr(a) => a.iter().for_each(|x| collect_part_ids(x, out)),
        _ => {}
    }
}

fn renumber_walk(pr: &mut Project, v: &mut Value, used: &mut HashSet<u64>, copy: bool, floor: Option<u64>) {
    match v {
        Value::Obj(m) => {
            if let Some(id) = part_id(m) {
                if used.contains(&id) {
                    let mut low = lowest(pr);
                    if let Some(f) = floor {
                        low = low.min(f);
                    }
                    for u in used.iter() {
                        low = low.min(*u);
                    }
                    let nid = low - 1;
                    pr.lib_low = nid;
                    used.insert(nid);
                    m.insert("id", Value::u(nid));
                } else {
                    used.insert(id);
                }
                if copy {
                    m.insert("guid", Value::Str(crate::rand::guid()));
                }
            }
            for (_, x) in m.items.iter_mut() {
                renumber_walk(pr, x, used, copy, floor);
            }
        }
        Value::Arr(a) => a.iter_mut().for_each(|x| renumber_walk(pr, x, used, copy, floor)),
        _ => {}
    }
}

