#!/usr/bin/env python3
"""Like /tmp/tools/cmp.py, with files placed where told (src=dst) and a cwd inside the temp dir.
usage: cmp2.py [-q] [-f src[=dst]]... [-C subdir] -- args...
As a module: compare(files, args, cwd_sub=None) -> (ok, report)."""
import os, re, subprocess, sys, tempfile, shutil, difflib
ORIG = '/workspace/executable'
MINE = '/workspace/.claude/worktrees/agent-af4bed457bbf53b4c/target/release/bimcraft-cli'
GUID = re.compile(r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}')


def norm(s, tmpdir=None):
    if tmpdir:
        s = s.replace(tmpdir, '<TMP>')
    s = re.sub(r'"uid": \d+', '"uid": <UID>', s)
    m = {}

    def rep(mo):
        g = mo.group(0)
        if g not in m:
            m[g] = 'GUID-%d' % (len(m) + 1)
        return m[g]
    s = GUID.sub(rep, s)
    s = re.sub(r"\.tmp[A-Za-z0-9]{6}", ".tmpXXXXXX", s)
    s = re.sub(r"/tmp/cmp[a-z0-9_]{8}", "<TMP>", s)
    return s


def run(exe, args, files, cwd_sub, dirs):
    d = tempfile.mkdtemp(prefix='cmp')
    for sd in dirs:
        os.makedirs(os.path.join(d, sd), exist_ok=True)
    for f in files:
        if '=' in f:
            src, dst = f.split('=', 1)
        else:
            src, dst = f, os.path.basename(f)
        full = os.path.join(d, dst)
        os.makedirs(os.path.dirname(full), exist_ok=True)
        shutil.copy(src, full)
    before = {}
    for root, ds, fs in os.walk(d):
        for f in fs:
            full = os.path.join(root, f)
            before[os.path.relpath(full, d)] = open(full, 'rb').read()
    cwd = os.path.join(d, cwd_sub) if cwd_sub else d
    p = subprocess.run([exe] + args, cwd=cwd, capture_output=True, timeout=300)
    out = {'stdout': p.stdout.decode('utf-8', 'replace'), 'stderr': p.stderr.decode('utf-8', 'replace'), 'code': p.returncode}
    fl = {}
    for root, ds, fs in os.walk(d):
        for f in fs:
            full = os.path.join(root, f)
            rel = os.path.relpath(full, d)
            data = open(full, 'rb').read()
            if before.get(rel) != data:
                fl[rel] = data
    shutil.rmtree(d)
    return out, fl, d


def compare(files, args, cwd_sub=None, dirs=(), maxlines=40):
    o, of, od = run(ORIG, args, files, cwd_sub, dirs)
    m, mf, md = run(MINE, args, files, cwd_sub, dirs)
    rep = []
    ok = True
    for k in ('code', 'stdout', 'stderr'):
        x = norm(str(o[k]), od)
        y = norm(str(m[k]), md)
        if x != y:
            ok = False
            rep.append('--- %s differs' % k)
            for l in list(difflib.unified_diff(x.splitlines(), y.splitlines(), 'orig', 'mine', lineterm='', n=0))[:maxlines]:
                rep.append(l[:400])
    for f in sorted(set(of) | set(mf)):
        if f not in of:
            ok = False
            rep.append('--- file %s only in mine' % f)
            continue
        if f not in mf:
            ok = False
            rep.append('--- file %s only in orig' % f)
            continue
        x, y = of[f], mf[f]
        try:
            xs = norm(x.decode('utf-8'), od)
            ys = norm(y.decode('utf-8'), md)
        except UnicodeDecodeError:
            if x != y:
                ok = False
                rep.append('--- binary file %s differs' % f)
            continue
        if xs != ys:
            ok = False
            rep.append('--- file %s differs' % f)
            for l in list(difflib.unified_diff(xs.splitlines(), ys.splitlines(), 'orig', 'mine', lineterm='', n=1))[:maxlines]:
                rep.append(l[:400])
    return ok, rep


def main():
    a = sys.argv[1:]
    files = []
    cwd_sub = None
    dirs = []
    while a and a[0] != '--':
        if a[0] == '-f':
            files.append(a[1]); a = a[2:]
        elif a[0] == '-C':
            cwd_sub = a[1]; a = a[2:]
        elif a[0] == '-d':
            dirs.append(a[1]); a = a[2:]
        else:
            break
    if a and a[0] == '--':
        a = a[1:]
    ok, rep = compare(files, a, cwd_sub, dirs)
    for l in rep:
        print(l)
    print('SAME' if ok else 'DIFF')
    sys.exit(0 if ok else 1)


